INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 9, 'theory', 'Квиз: iproute2 и маршрутизация');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 0, 'В таблице есть маршруты: 10.0.0.0/8 с метрикой 1, 10.1.0.0/16 с метрикой 100 и default с метрикой 0. Какой маршрут выберет ядро для адреса 10.1.2.3?', '["default, потому что у него метрика 0", "10.0.0.0/8, потому что у него метрика 1", "10.1.0.0/16, потому что префикс длиннее", "Любой из трёх, выбор случайный"]', 2, 'Сначала сравнивается длина префикса: /16 длиннее /8 и /0. Метрика решает только между маршрутами с одинаковым префиксом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 1, 'ss -tln показывает строку LISTEN на 127.0.0.1:6379. Откуда можно подключиться к этому порту?', '["Только с самого хоста", "Из любой сети, подключённой к хосту", "Только из той же подсети, что и eth0", "Только от процессов root"]', 0, 'Адрес 127.0.0.1 принадлежит петлевому интерфейсу, поэтому сокет принимает соединения только изнутри хоста. Для доступа снаружи нужен 0.0.0.0, [::] или адрес внешнего интерфейса.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 2, 'Сервер с двумя провайдерами отвечает на пакеты, пришедшие по второму каналу, через первый, и ответы теряются. Что делает правильную пересылку?', '["Понизить метрику default в main до 0", "Включить net.ipv4.ip_forward", "Удалить маршрут proto kernel", "Таблица с default через второго провайдера и правило from адрес lookup таблица"]', 3, 'В main один шлюз по умолчанию, поэтому нужен выбор по адресу отправителя: свой набор маршрутов и правило ip rule, которое направляет в него пакеты с адресом второго провайдера.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 3, 'Что чаще всего означает запись FAILED в ip neigh?', '["Адрес занят двумя хостами сразу", "На запросы арп или обнаружения соседей не пришёл ответ", "Запись добавил администратор и она не стареет", "Интерфейс в состоянии LOWERLAYERDOWN"]', 1, 'FAILED ставится, когда проб отправлено максимум, а ответа нет: сосед выключен, в другой сети или не отвечает. Запись, которая не стареет, называется PERMANENT.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 4, 'net.ipv4.conf.all.rp_filter = 2, а net.ipv4.conf.eth1.rp_filter = 0. Какой режим проверки обратного пути действует на eth1?', '["Выключен, так как у eth1 стоит 0", "Строгий", "Свободный, так как берётся большее из двух значений", "Режим выбирает само приложение"]', 2, 'Для проверки на интерфейсе берётся максимум из значений all и самого интерфейса: max(2, 0) = 2, а это свободный режим.');
